\pset pager off
\copy (WITH fam AS (SELECT j.id, CASE WHEN j.title ~* '\yquant(itative)?\s+(researcher|analyst|strategist|trader)\y|\yalpha\s+research' THEN 'Quantitative Researcher' WHEN j.title ~* '\ydata scientist|\ydata science\y' THEN 'Data Scientist' WHEN j.title ~* '\yai engineer\y|\yapplied ai\y|\yllm engineer\y|\ygen(erative)? ai engineer\y|\yai/ml engineer\y|\yai\y[\w /&-]{0,18}\yengineer\y|\yengineer\y[\w /&-]{0,12}\yai\y|\ysoftware engineer\y[\s,-]*\yai\y|\ydeep learning\y|\ynlp engineer\y|\ycomputer vision engineer\y' THEN 'AI Engineer' WHEN j.title ~* '\ymachine learning engineer\y|\yml engineer\y|\ymlops\y|\yml ops\y|\ymachine learning scientist\y' THEN 'ML Engineer' WHEN j.title ~* '\yanalytics engineer|\yanalytics engineering\y' THEN 'Analytics Engineer' WHEN j.title ~* '\ydata analyst|\ybusiness intelligence\y|\ybi analyst\y' THEN 'Data Analyst' WHEN j.title ~* '\ydata engineer|\ydata platform engineer\y' THEN 'Data Engineer' WHEN j.title ~* '\yresearch scientist\y|\yapplied scientist\y|\yresearch engineer\y' THEN 'Research Scientist' WHEN j.title ~* '\yforward deployed\y|\ysolutions? engineer\y' THEN 'Forward Deployed' END AS family FROM jobs j) SELECT f.family, lower(m.skill) AS phrase, count(DISTINCT m.job_id) AS n, sum((m.required)::int) AS n_req FROM job_skill_mentions m JOIN fam f ON f.id = m.job_id WHERE f.family IS NOT NULL GROUP BY 1,2 HAVING count(DISTINCT m.job_id) >= 3) TO STDOUT WITH CSV HEADER
